package com.vandorlabs.copier;

import com.vandorlabs.blocks.*;
import com.vandorlabs.surface.SquareLayout;
import com.vandorlabs.tiles.DeferredTileLoad;
import com.vandorlabs.vehicle.*;
import com.vandorlabs.redstone.ChannelList;
import java.util.*;
import net.minecraft.block.*;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.nbt.*;
import net.minecraft.tileentity.*;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.WorldServer;

/** Preflight geometry and economic checks never submit a transaction or touch its journal queue. */
public final class CopyPlanRuntimeChecks {
    private static int assertions;
    private static void require(boolean value,String message){assertions++;if(!value)throw new IllegalStateException("Copy preflight: "+message);}
    private interface Attempt{void run()throws Exception;}
    private static void refuses(Attempt attempt,String text)throws Exception{boolean denied=false;try{attempt.run();}catch(IllegalArgumentException expected){denied=text==null||expected.getMessage()!=null&&expected.getMessage().contains(text);}require(denied,"expected whole-plan refusal: "+text);}
    private static Block block(String id){return Block.getBlockFromName("vandorlabs:"+id);}
    private static final class Fixture{
        final WorldServer world;final EntityPlayerMP actor;final BlockPos base;final EnumFacing front,right;final CopyControllerTile owner;
        Fixture(WorldServer world,EntityPlayerMP actor,BlockPos base,EnumFacing front,int size){this.world=world;this.actor=actor;this.base=base;this.front=front;right=front.rotateYCCW();clear(world,base);
            world.setBlockState(base,block("copy_controller").getDefaultState().withProperty(BlockVandorDirectional.FACING,front),2);
            for(int side:new int[]{-1,1})for(int u=0;u<size;u++)for(int v=0;v<size;v++)world.setBlockState(base.offset(right,side*(u+1)).offset(front,v),block("turntable_surface").getDefaultState().withProperty(BlockTurntableSurface.FACING,EnumFacing.UP),2);
            DeferredTileLoad.flush(world);owner=(CopyControllerTile)world.getTileEntity(base);owner.settings(1,0,0,ChannelList.EMPTY);owner.refreshPads(actor);require(owner.input.size==size&&owner.output.size==size&&Collections.disjoint(owner.input.cells,owner.output.cells),"matching disjoint square claims "+front+size);
        }
        BlockPos source(){return CopyPlan.volume(owner.input,owner.height)[0];}
        BlockPos target(){return CopyPlan.volume(owner.output,owner.height)[0];}
        CopyPlan plan()throws Exception{return CopyPlan.prepare(owner,actor);}
        TileEntityChest supply(ItemStack... items){world.setBlockState(owner.chest(),Blocks.CHEST.getDefaultState(),2);TileEntityChest chest=(TileEntityChest)world.getTileEntity(owner.chest());for(int i=0;i<items.length;i++)chest.setInventorySlotContents(i,items[i].copy());return chest;}
    }
    public static void run(WorldServer world,EntityPlayerMP actor)throws Exception{
        assertions=0;BlockPos base=new BlockPos(610,110,210);boolean creative=actor.capabilities.isCreativeMode;
        for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.getChunkFromChunkCoords((base.getX()>>4)+x,(base.getZ()>>4)+z);
        try{geometry();actor.capabilities.isCreativeMode=true;
            for(EnumFacing front:EnumFacing.HORIZONTALS){Fixture f=new Fixture(world,actor,base,front,2);IBlockState stairs=Blocks.OAK_STAIRS.getDefaultState().withProperty(BlockStairs.FACING,front).withProperty(BlockStairs.HALF,BlockStairs.EnumHalf.TOP);world.setBlockState(f.source(),stairs,2);CopyPlan plan=f.plan();require(plan.supply==null&&plan.materials.isEmpty(),"Creative needs no chest or item accounting");require(plan.result.cells.size()==1&&plan.result.cells.get(0).state==stairs&&plan.original.matches(world,plan.sourceOrigin),"four-facing plan preserves exact orientation and source");require(world.isAirBlock(f.target()),"preflight leaves output untouched");}
            quantities(world,actor,base);inventories(world,actor,base);channels(world,actor,base);boundaries(world,actor,base);programmerCost(world);
        }finally{actor.capabilities.isCreativeMode=creative;clear(world,base);}
        System.out.println("[vandorlabs][reprolab] copy-plan PASS assertions="+assertions+" six-normal prism geometry four controller facings square claims exact Survival inventory costs source/supply preservation Creative bypass signed/overflow channels Programmer/slab/snow quantities");
    }
    private static void geometry(){for(EnumFacing normal:EnumFacing.values())for(int size:new int[]{1,4,16})for(int height:new int[]{1,16}){com.vandorlabs.turntable.TurntableGeometry.Face basis=com.vandorlabs.turntable.TurntableGeometry.Face.valueOf(normal.name());Set<BlockPos> cells=new HashSet<>();for(int u=0;u<size;u++)for(int v=0;v<size;v++){double[] p=basis.point(u,v,0);cells.add(new BlockPos(p[0],p[1],p[2]));}SquareLayout square=SquareLayout.of(cells,normal);BlockPos[] bounds=CopyPlan.volume(square,height);long volume=(long)(bounds[1].getX()-bounds[0].getX()+1)*(bounds[1].getY()-bounds[0].getY()+1)*(bounds[1].getZ()-bounds[0].getZ()+1);require(volume==(long)size*size*height,"scan prism size/height "+normal+size+height);for(BlockPos cell:square.cells){BlockPos first=cell.offset(normal),last=cell.offset(normal,height);require(inside(first,bounds)&&inside(last,bounds)&&!inside(cell,bounds),"volume begins one block beyond surface and includes full configured height");}require(SquareLayout.read(square.write()).cells.equals(square.cells),"square save round trip");}}
    private static boolean inside(BlockPos p,BlockPos[] bounds){return p.getX()>=bounds[0].getX()&&p.getY()>=bounds[0].getY()&&p.getZ()>=bounds[0].getZ()&&p.getX()<=bounds[1].getX()&&p.getY()<=bounds[1].getY()&&p.getZ()<=bounds[1].getZ();}
    private static void quantities(WorldServer world,EntityPlayerMP actor,BlockPos base)throws Exception{
        actor.capabilities.isCreativeMode=false;Fixture slab=new Fixture(world,actor,base,EnumFacing.NORTH,1);world.setBlockState(slab.source(),Blocks.DOUBLE_STONE_SLAB.getDefaultState(),2);TileEntityChest supply=slab.supply(new ItemStack(Blocks.STONE_SLAB));NBTTagCompound before=supply.writeToNBT(new NBTTagCompound());refuses(slab::plan,"Missing material:");require(before.equals(supply.writeToNBT(new NBTTagCompound()))&&world.isAirBlock(slab.target()),"slab shortage leaves supply/output untouched");supply.setInventorySlotContents(0,new ItemStack(Blocks.STONE_SLAB,2));CopyPlan paid=slab.plan();require(paid.materials.size()==1&&paid.materials.get(0).count==2,"double slab needs two slab items");require(paid.supply.before.matches(world,paid.supply.origin)&&!paid.supply.after.matches(world,paid.supply.origin),"withdrawal is planned without spending supply");
        Fixture snow=new Fixture(world,actor,base,EnumFacing.NORTH,1);world.setBlockState(snow.source(),Blocks.SNOW_LAYER.getDefaultState().withProperty(BlockSnow.LAYERS,7),2);snow.supply(new ItemStack(Blocks.SNOW_LAYER,7));CopyPlan layers=snow.plan();require(layers.materials.size()==1&&layers.materials.get(0).count==7,"seven snow layers need seven items");
        Fixture loot=new Fixture(world,actor,base,EnumFacing.NORTH,1);world.setBlockState(loot.source(),Blocks.CHEST.getDefaultState(),2);((TileEntityChest)world.getTileEntity(loot.source())).setLootTable(new net.minecraft.util.ResourceLocation("minecraft:chests/simple_dungeon"),123L);loot.supply(new ItemStack(Blocks.CHEST));NBTTagCompound original=world.getTileEntity(loot.source()).writeToNBT(new NBTTagCompound());refuses(loot::plan,"Open loot");require(original.equals(world.getTileEntity(loot.source()).writeToNBT(new NBTTagCompound())),"refused Survival loot stays unopened");actor.capabilities.isCreativeMode=true;CopyPlan creative=loot.plan();require(creative.result.cells.get(0).tileData().hasKey("LootTable",8)&&creative.supply==null,"Creative retains unopened loot data without material chest");
    }
    private static ItemStack nested(){ItemStack item=new ItemStack(Blocks.PURPLE_SHULKER_BOX);NBTTagCompound data=new NBTTagCompound(),diamond=new ItemStack(Items.DIAMOND,3).writeToNBT(new NBTTagCompound());diamond.setByte("Slot",(byte)0);NBTTagList slots=new NBTTagList();slots.appendTag(diamond);data.setTag("Items",slots);data.setString("CustomName","Preflight nested cargo");item.setTagInfo("BlockEntityTag",data);return item;}
    private static void inventories(WorldServer world,EntityPlayerMP actor,BlockPos base)throws Exception{
        actor.capabilities.isCreativeMode=false;Fixture f=new Fixture(world,actor,base,EnumFacing.NORTH,1);world.setBlockState(f.source(),Blocks.CHEST.getDefaultState(),2);TileEntityChest chest=(TileEntityChest)world.getTileEntity(f.source());chest.setCustomName("Preserved source");ItemStack named=new ItemStack(Items.PAPER,2);named.setStackDisplayName("Exact named cargo");ItemStack nested=nested();chest.setInventorySlotContents(0,nested);chest.setInventorySlotContents(1,named);TileEntityChest supply=f.supply(new ItemStack(Blocks.CHEST),nested,new ItemStack(Items.PAPER,2));NBTTagCompound source=chest.writeToNBT(new NBTTagCompound()),before=supply.writeToNBT(new NBTTagCompound());refuses(f::plan,"Missing material:");require(before.equals(supply.writeToNBT(new NBTTagCompound()))&&source.equals(chest.writeToNBT(new NBTTagCompound())),"wrong named-item payment cannot change source or supply");supply.setInventorySlotContents(2,named.copy());supply.setInventorySlotContents(26,new ItemStack(Items.EMERALD,7));before=supply.writeToNBT(new NBTTagCompound());CopyPlan plan=f.plan();require(plan.materials.stream().filter(n->n.exact).count()==2,"nested carrier charged once as exact item plus exact named paper");require(plan.materials.stream().noneMatch(n->n.item.getItem()==Items.DIAMOND),"contents inside paid shulker not charged twice");require(source.equals(chest.writeToNBT(new NBTTagCompound()))&&before.equals(supply.writeToNBT(new NBTTagCompound()))&&plan.original.matches(world,plan.sourceOrigin),"successful preflight preserves full source/supply NBT");VehicleWorld result=new VehicleWorld(world,plan.result);TileEntityChest cloned=(TileEntityChest)result.getTileEntity(BlockPos.ORIGIN);require(cloned.getName().equals("Preserved source")&&ItemStack.areItemStacksEqual(cloned.getStackInSlot(0),nested)&&ItemStack.areItemStacksEqual(cloned.getStackInSlot(1),named),"planned output retains names and nested item data");VehicleWorld after=new VehicleWorld(world,plan.supply.after);net.minecraft.inventory.IInventory remaining=(net.minecraft.inventory.IInventory)after.getTileEntity(BlockPos.ORIGIN);require(remaining.getStackInSlot(26).getCount()==7&&remaining.getStackInSlot(0).isEmpty()&&remaining.getStackInSlot(1).isEmpty()&&remaining.getStackInSlot(2).isEmpty(),"planned payment spends only exact requirements");
    }
    private static void channels(WorldServer world,EntityPlayerMP actor,BlockPos base)throws Exception{
        actor.capabilities.isCreativeMode=true;for(int delta:new int[]{7,-7}){Fixture f=new Fixture(world,actor,base,EnumFacing.NORTH,1);f.owner.settings(2,delta,0,ChannelList.EMPTY);world.setBlockState(f.source(),Blocks.STONE.getDefaultState(),2);world.setBlockState(f.source().up(),block("programmable_pressure_plate").getDefaultState(),2);com.vandorlabs.plate.PlateTile plate=(com.vandorlabs.plate.PlateTile)world.getTileEntity(f.source().up());plate.configure(com.vandorlabs.tiles.ScreenHousingTextures.DEFAULT_TRAPDOOR,1,ChannelList.of(500));NBTTagCompound before=plate.writeToNBT(new NBTTagCompound());CopyPlan plan=f.plan();com.vandorlabs.plate.PlateTile cloned=(com.vandorlabs.plate.PlateTile)new VehicleWorld(world,plan.result).getTileEntity(new BlockPos(0,1,0));require(cloned.getRedstoneChannels().equals(ChannelList.of(500+delta))&&plate.getRedstoneChannels().equals(ChannelList.of(500)),"actual plate signed channel offset "+delta);require(before.equals(plate.writeToNBT(new NBTTagCompound()))&&plan.original.matches(world,plan.sourceOrigin),"channel transform never edits source");}
        for(int[] limits:new int[][]{{65535,1},{1,-1}}){Fixture f=new Fixture(world,actor,base,EnumFacing.NORTH,1);f.owner.settings(2,limits[1],0,ChannelList.EMPTY);world.setBlockState(f.source(),Blocks.STONE.getDefaultState(),2);world.setBlockState(f.source().up(),block("programmable_pressure_plate").getDefaultState(),2);((com.vandorlabs.plate.PlateTile)world.getTileEntity(f.source().up())).configure(com.vandorlabs.tiles.ScreenHousingTextures.DEFAULT_TRAPDOOR,1,ChannelList.of(limits[0]));actor.capabilities.isCreativeMode=false;TileEntityChest supply=f.supply(new ItemStack(Blocks.STONE),new ItemStack(block("programmable_pressure_plate")));NBTTagCompound before=supply.writeToNBT(new NBTTagCompound());refuses(f::plan,"cannot be shifted");require(before.equals(supply.writeToNBT(new NBTTagCompound()))&&world.isAirBlock(f.target()),"channel bound refusal precedes any economic mutation");actor.capabilities.isCreativeMode=true;}
    }
    private static void boundaries(WorldServer world,EntityPlayerMP actor,BlockPos base)throws Exception{
        actor.capabilities.isCreativeMode=true;for(EnumFacing front:EnumFacing.HORIZONTALS){Fixture f=new Fixture(world,actor,base,front,2);BlockPos corner=base.offset(f.right,2).offset(front);world.removeTileEntity(corner);world.setBlockState(corner,Blocks.AIR.getDefaultState(),2);refuses(()->f.owner.refreshPads(actor),"filled square");}
        Fixture occupied=new Fixture(world,actor,base,EnumFacing.NORTH,1);world.setBlockState(occupied.source(),Blocks.STONE.getDefaultState(),2);world.setBlockState(occupied.target(),Blocks.GLASS.getDefaultState(),2);refuses(occupied::plan,"occupied");require(world.getBlockState(occupied.target()).getBlock()==Blocks.GLASS,"occupied output cannot be overwritten");
        Fixture immovable=new Fixture(world,actor,base,EnumFacing.NORTH,1);world.setBlockState(immovable.source(),Blocks.BEDROCK.getDefaultState(),2);refuses(immovable::plan,"unbreakable");require(world.isAirBlock(immovable.target()),"unsupported source leaves output empty");
        Fixture mixed=new Fixture(world,actor,base,EnumFacing.NORTH,1);world.setBlockState(base.offset(mixed.right),block("turntable_surface").getDefaultState().withProperty(BlockTurntableSurface.FACING,EnumFacing.DOWN),2);refuses(()->mixed.owner.refreshPads(actor),"same direction");
    }
    private static void programmerCost(WorldServer world){com.vandorlabs.programmer.ProgrammerBlock programmer=(com.vandorlabs.programmer.ProgrammerBlock)block("data_chip_programmer");List<VehicleStructure.Cell> cells=new ArrayList<>();com.vandorlabs.programmer.ProgrammerTile tile=new com.vandorlabs.programmer.ProgrammerTile();tile.setPos(BlockPos.ORIGIN);tile.setInventorySlotContents(0,new ItemStack(Items.PAPER));for(int part=0;part<4;part++){BlockPos at=com.vandorlabs.programmer.ProgrammerBlock.cell(BlockPos.ORIGIN,EnumFacing.NORTH,part);cells.add(new VehicleStructure.Cell(at,programmer.getDefaultState().withProperty(com.vandorlabs.programmer.ProgrammerBlock.PART,part),part==0?tile.writeToNBT(new NBTTagCompound()):null));}VehicleStructure snapshot=VehicleStructure.display(cells);List<CopyMaterials.Need> needs=CopyMaterials.forSnapshot(snapshot,new VehicleWorld(world,snapshot),false);long bodies=0,paper=0;for(CopyMaterials.Need need:needs){if(need.item.getItem()==Item.getItemFromBlock(programmer))bodies+=need.count;if(need.item.getItem()==Items.PAPER)paper+=need.count;}require(bodies==1&&paper==1,"four-cell Programmer costs one body and its single-slot item once");}
    private static void clear(WorldServer world,BlockPos base){for(BlockPos cursor:BlockPos.getAllInBox(base.add(-5,-2,-5),base.add(5,5,5))){BlockPos p=cursor.toImmutable();world.removeTileEntity(p);world.setBlockState(p,Blocks.AIR.getDefaultState(),2);}}
    private CopyPlanRuntimeChecks(){}
}
